root:
rules_version = '2+modules';

// One ruleset for every game. Each game's rules live next to the game and are
// imported here; each match block starts every update rule with a comparison
// the other transitions can't pass, so a write pays for its own branch only.

import {
  ticTacToeCreate, ticTacToeJoin, ticTacToeCancel,
  ticTacToeMove, ticTacToeWin, ticTacToeDraw, ticTacToeResign
} from '../games/tictactoe/tictactoe';
import {
  unoCreate, unoJoin, unoStart, unoDeal, unoPlay, unoDraw, unoCancel,
  unoDeckCreate, unoDeckRead, unoDrawsCreate, unoPlayedCreate
} from '../games/uno/uno';
import {
  poolCreate, poolJoin, poolCancel, poolShot, poolFinish, poolResign
} from '../games/pool/pool';
import {
  battleshipCreate, battleshipJoin, battleshipCancel, battleshipReady, battleshipBoardCreate,
  battleshipBoardRead, battleshipShotCreate, battleshipShot, battleshipResign
} from '../games/battleship/battleship';
import { chessCreate, chessJoin, chessCancel, chessMove, chessResign } from '../games/chess/chess';
import { checkersCreate, checkersJoin, checkersCancel, checkersMove, checkersResign } from '../games/checkers/checkers';
import {
  yachtCreate, yachtJoin, yachtCancel, yachtStart, yachtCommit, yachtNonce, yachtReveal, yachtScore
} from '../games/yacht/yacht';
import {
  reversiCreate, reversiJoin, reversiCancel, reversiMove, reversiPass, reversiResign
} from '../games/reversi/reversi';
import {
  airHockeyCreate, airHockeyJoin, airHockeyCancel, airHockeyFinish, airHockeyForfeit, airHockeyResign
} from '../games/air-hockey/airhockey';
import { sokobanScoreCreate, sokobanScoreImprove } from '../games/sokoban/sokoban';
import { rematchCreate, newMatchOrRematch } from '../packages/turn-net/rematch';

service cloud.firestore {
  match /databases/{database}/documents {
    match /tictactoe/{matchId} {
      allow read: if request.auth != null;
      allow create: if ticTacToeCreate() && newMatchOrRematch(database, 'tictactoe');
      allow delete: if ticTacToeCancel();
      allow update: if resource.data.status == 'waiting' && (ticTacToeJoin());
      allow update: if request.resource.data.status == 'playing' && resource.data.status == 'playing' && (ticTacToeMove());
      allow update: if request.resource.data.winner == 'host' && request.resource.data.status == 'won' && (ticTacToeWin('host'));
      allow update: if request.resource.data.winner == 'guest' && request.resource.data.status == 'won' && (ticTacToeWin('guest'));
      allow update: if request.resource.data.status == 'draw' && (ticTacToeDraw());
      allow update: if request.resource.data.status == 'resigned' && (ticTacToeResign());
    }
    match /uno/{matchId} {
      allow read: if request.auth != null;
      allow create: if unoCreate();
      allow delete: if unoCancel();
      allow update: if request.resource.data.lastAction == 'join' && (unoJoin());
      allow update: if request.resource.data.lastAction == 'start' && (unoStart());
      allow update: if request.resource.data.lastAction == 'deal' && (unoDeal(database, matchId));
      allow update: if request.resource.data.lastAction == 'play' && (unoPlay(database, matchId));
      allow update: if request.resource.data.lastAction in ['draw', 'pass'] && (unoDraw());

      match /deck/{i} {
        allow get: if request.auth != null && unoDeckRead(database, matchId, i);
        allow create: if unoDeckCreate(database, matchId, i);
      }
      match /draws/{i} {
        allow read: if request.auth != null && resource.data.uid == request.auth.uid;
        allow create: if request.auth != null && unoDrawsCreate(database, matchId, i);
      }
      match /played/{i} {
        allow read: if request.auth != null;
        allow create: if request.auth != null && unoPlayedCreate(database, matchId, i);
      }
    }
    match /pool/{matchId} {
      allow read: if request.auth != null;
      allow create: if poolCreate() && newMatchOrRematch(database, 'pool');
      allow delete: if poolCancel();
      allow update: if resource.data.status == 'waiting' && (poolJoin());
      allow update: if request.resource.data.status == 'playing' && resource.data.status == 'playing' && (poolShot());
      allow update: if request.resource.data.status == 'won' && (poolFinish());
      allow update: if request.resource.data.status == 'resigned' && (poolResign());
    }
    match /battleship/{matchId} {
      allow read: if request.auth != null;
      allow create: if battleshipCreate() && newMatchOrRematch(database, 'battleship');
      allow delete: if battleshipCancel();
      allow update: if request.resource.data.status == 'placing' && resource.data.status == 'waiting' && (battleshipJoin());
      allow update: if resource.data.status == 'placing' && (battleshipReady(database, matchId));
      allow update: if resource.data.status == 'playing' && request.resource.data.status != 'resigned' && (battleshipShot(database, matchId));
      allow update: if request.resource.data.status == 'resigned' && (battleshipResign());

      match /boards/{uid} {
        allow get: if battleshipBoardRead(database, matchId, uid);
        allow create: if battleshipBoardCreate(database, matchId, uid);
      }
      match /shots/{shotId} {
        allow read: if request.auth != null;
        allow create: if battleshipShotCreate(database, matchId, shotId);
      }
    }
    match /chess/{matchId} {
      allow read: if request.auth != null;
      allow create: if chessCreate() && newMatchOrRematch(database, 'chess');
      allow delete: if chessCancel();
      allow update: if resource.data.status == 'waiting' && (chessJoin());
      allow update: if resource.data.status == 'playing' && request.resource.data.status in ['playing', 'won', 'draw'] && (chessMove());
      allow update: if request.resource.data.status == 'resigned' && (chessResign());
    }
    match /checkers/{matchId} {
      allow read: if request.auth != null;
      allow create: if checkersCreate() && newMatchOrRematch(database, 'checkers');
      allow delete: if checkersCancel();
      allow update: if resource.data.status == 'waiting' && (checkersJoin());
      allow update: if resource.data.status == 'playing' && request.resource.data.status in ['playing', 'won'] && (checkersMove());
      allow update: if request.resource.data.status == 'resigned' && (checkersResign());
    }
    match /yacht/{matchId} {
      allow read: if request.auth != null;
      allow create: if yachtCreate();
      allow delete: if yachtCancel();
      allow update: if request.resource.data.lastAction == 'join' && (yachtJoin());
      allow update: if request.resource.data.lastAction == 'start' && (yachtStart());
      allow update: if request.resource.data.lastAction == 'commit' && (yachtCommit());
      allow update: if request.resource.data.lastAction == 'nonce' && (yachtNonce());
      allow update: if request.resource.data.lastAction == 'reveal' && (yachtReveal());
      allow update: if request.resource.data.lastAction == 'score' && (yachtScore());
    }
    match /reversi/{matchId} {
      allow read: if request.auth != null;
      allow create: if reversiCreate() && newMatchOrRematch(database, 'reversi');
      allow delete: if reversiCancel();
      allow update: if resource.data.status == 'waiting' && (reversiJoin());
      allow update: if request.resource.data.lastMove.at != '' && request.resource.data.status in ['playing', 'won', 'draw'] && (reversiMove());
      allow update: if request.resource.data.lastMove.at == '' && request.resource.data.status == 'playing' && (reversiPass());
      allow update: if request.resource.data.status == 'resigned' && (reversiResign());
    }
    match /airhockey/{matchId} {
      allow read: if request.auth != null;
      allow create: if airHockeyCreate() && newMatchOrRematch(database, 'airhockey');
      allow delete: if airHockeyCancel();
      allow update: if resource.data.status == 'waiting' && (airHockeyJoin());
      allow update: if request.resource.data.endedBy == 'goals' && (airHockeyFinish());
      allow update: if request.resource.data.endedBy == 'forfeit' && (airHockeyForfeit());
      allow update: if request.resource.data.status == 'resigned' && (airHockeyResign());
    }
    match /sokoban/{level}/scores/{uid} {
      allow read: if request.auth != null;
      allow create: if sokobanScoreCreate(level, uid);
      allow update: if sokobanScoreImprove(level, uid);
    }
    match /rematches/{game}/matches/{matchId} {
      allow read: if request.auth != null;
      allow create: if rematchCreate(database, game, matchId);
    }
    match /{document=**} {
      allow read, write: if false;
    }
  }
}

modules.../games/air-hockey/airhockey:
rules_version = '2+modules';

import { validCreate, validJoin, canCancel } from 'lobby';
import { onlyFieldsChanged } from 'lifecycle';
import { isPlaying } from 'state';
import { resignedBy } from 'results';

// Air hockey match rules. The lobby and the result live here; live play
// lives in the Realtime Database. The match document follows the stdlib
// convention (host, guest, currentTurn, status, winner, moveCount), with
// currentTurn fixed at 'host' and moveCount at 0 since there are no turns,
// plus `score` {host, guest} and `endedBy`: '' while open, 'goals' or
// 'forfeit' once won.
//
// Rules can't run the physics or read the Realtime Database, so they check
// the result's shape and consistency only: a win on goals is recorded by the
// host (who runs the physics) with one side at 7 and the other below it,
// naming that side the winner; a forfeit is recorded by a player naming
// themself the winner with neither side at 7. Whether the other player had
// really left, and whether the score is the live one, is checked by every
// client against the live match (resultMatchesLive), whose rules verify the
// forfeit against presence and the score goal by goal.

function airHockeyScoreIs(s, hostMax, guestMax) {
  return s.keys().hasOnly(['host', 'guest'])
    && s.host is int && s.guest is int
    && s.host >= 0 && s.host <= hostMax
    && s.guest >= 0 && s.guest <= guestMax;
}

export function airHockeyCreate() {
  return validCreate()
    && request.resource.data.keys().hasOnly(['host', 'guest', 'currentTurn', 'status', 'winner', 'moveCount',
         'score', 'endedBy', 'createdAt', 'rematchOf'])
    && request.resource.data.currentTurn == 'host'
    && request.resource.data.winner == ''
    && request.resource.data.moveCount == 0
    && request.resource.data.createdAt == request.time
    && request.resource.data.score == {'host': 0, 'guest': 0}
    && request.resource.data.endedBy == '';
}

export function airHockeyJoin() {
  return validJoin() && onlyFieldsChanged(['guest', 'status']);
}

export function airHockeyCancel() {
  return canCancel();
}

// The host records a side reaching 7 goals.
export function airHockeyFinish() {
  let s = request.resource.data.score;
  let w = request.resource.data.winner;
  return request.auth != null && isPlaying()
    && request.auth.uid == resource.data.host
    && request.resource.data.status == 'won'
    && ((w == 'host' && s.host == 7 && airHockeyScoreIs(s, 7, 6))
      || (w == 'guest' && s.guest == 7 && airHockeyScoreIs(s, 6, 7)))
    && onlyFieldsChanged(['status', 'winner', 'score', 'endedBy']);
}

// A player records that the other left, and names themself the winner.
export function airHockeyForfeit() {
  let uid = request.auth.uid;
  return request.auth != null && isPlaying()
    && (uid == resource.data.host || uid == resource.data.guest)
    && request.resource.data.status == 'won'
    && request.resource.data.winner == (uid == resource.data.host ? 'host' : 'guest')
    && airHockeyScoreIs(request.resource.data.score, 6, 6)
    && onlyFieldsChanged(['status', 'winner', 'score', 'endedBy']);
}

// The caller resigns their own seat; the other seat wins.
export function airHockeyResign() {
  return resignedBy(request.auth.uid == resource.data.host ? 'host' : 'guest');
}

modules.../games/battleship/battleship:
rules_version = '2+modules';

import { onlyFieldsChanged } from 'lifecycle';
import { isMyTurn } from 'turns';
import { resignedBy } from 'results';
import { ownerOnlyUntil } from 'content';

// Battleship match rules. The match document follows the stdlib convention
// (host, guest, currentTurn, status, winner, moveCount) plus hostReady,
// guestReady, hostHits, guestHits (hits each seat scored) and lastShot.
//
// Each fleet is boards/{uid}: readable only by its owner until the match
// ends, and create-only, so ships can't move after placement. A shot is the
// create-only document shots/{h|g}{cell} plus a match update in one batch.
// The shot rule reads the defender's fleet with get() and requires the
// reported hit to match it, so the attacker never sees the fleet and the
// answer is still enforced.

function bsCells5(s, k) {
  return [s, s + k, s + 2 * k, s + 3 * k, s + 4 * k];
}

function bsCells4(s, k) {
  return [s, s + k, s + 2 * k, s + 3 * k];
}

function bsCells3(s, k) {
  return [s, s + k, s + 2 * k];
}

function bsCells2(s, k) {
  return [s, s + k];
}

function bsStep(dir) {
  return dir == 'h' ? 1 : 10;
}

// A ship of `len` from `s` stays on the board: across a row, or down the columns.
function bsInBounds(s, dir, len) {
  return s is int && s >= 0 && s <= 99 && dir in ['h', 'v']
    && (dir == 'h' ? s % 10 + len - 1 <= 9 : s + (len - 1) * 10 <= 99);
}

// The five ships in order (5, 4, 3, 3, 2), each on the board, and `cells` is
// exactly their cells; 17 distinct cells means no two ships overlap.
function bsValidFleet() {
  let st = request.resource.data.starts;
  let d = request.resource.data.dirs;
  return request.resource.data.keys().hasOnly(['starts', 'dirs', 'cells'])
    && request.resource.data.starts.size() == 5
    && request.resource.data.dirs.size() == 5
    && bsInBounds(st[0], d[0], 5) && bsInBounds(st[1], d[1], 4) && bsInBounds(st[2], d[2], 3)
    && bsInBounds(st[3], d[3], 3) && bsInBounds(st[4], d[4], 2)
    && request.resource.data.cells == bsCells5(st[0], bsStep(d[0])).concat(bsCells4(st[1], bsStep(d[1])))
         .concat(bsCells3(st[2], bsStep(d[2]))).concat(bsCells3(st[3], bsStep(d[3])))
         .concat(bsCells2(st[4], bsStep(d[4])))
    && request.resource.data.cells.toSet().size() == 17;
}

export function battleshipCreate() {
  return request.auth != null
    && request.resource.data.keys().hasOnly(['host', 'guest', 'currentTurn', 'status', 'winner', 'moveCount',
         'hostReady', 'guestReady', 'hostHits', 'guestHits', 'lastShot', 'createdAt', 'rematchOf'])
    && request.resource.data.host == request.auth.uid
    && request.resource.data.guest == ''
    && request.resource.data.status == 'waiting'
    && request.resource.data.currentTurn == 'host'
    && request.resource.data.winner == ''
    && request.resource.data.moveCount == 0
    && request.resource.data.hostReady == false
    && request.resource.data.guestReady == false
    && request.resource.data.hostHits == 0
    && request.resource.data.guestHits == 0
    && request.resource.data.lastShot == ''
    && request.resource.data.createdAt == request.time;
}

export function battleshipJoin() {
  return request.auth != null
    && resource.data.status == 'waiting'
    && resource.data.guest == ''
    && request.auth.uid != resource.data.host
    && request.resource.data.guest == request.auth.uid
    && request.resource.data.status == 'placing'
    && onlyFieldsChanged(['guest', 'status']);
}

export function battleshipCancel() {
  return request.auth != null && resource.data.status == 'waiting' && request.auth.uid == resource.data.host;
}

// A player marks their seat ready in the batch that writes their fleet; the
// second ready player starts the battle.
export function battleshipReady(db, id) {
  let seat = request.auth.uid == resource.data.host ? 'host' : 'guest';
  let other = seat == 'host' ? 'guest' : 'host';
  return request.auth != null
    && resource.data.status == 'placing'
    && (request.auth.uid == resource.data.host || request.auth.uid == resource.data.guest)
    && resource.data[seat + 'Ready'] == false
    && request.resource.data[seat + 'Ready'] == true
    && existsAfter(/databases/$(db)/documents/battleship/$(id)/boards/$(request.auth.uid))
    && request.resource.data.status == (resource.data[other + 'Ready'] ? 'playing' : 'placing')
    && onlyFieldsChanged([seat + 'Ready', 'status']);
}

export function battleshipBoardCreate(db, id, uid) {
  let m = get(/databases/$(db)/documents/battleship/$(id)).data;
  return request.auth != null
    && request.auth.uid == uid
    && (uid == m.host || uid == m.guest)
    && m.status == 'placing'
    && bsValidFleet();
}

// The owner reads their fleet at any time without a read of the match; the
// other player reads it once the match is won or resigned.
export function battleshipBoardRead(db, id, uid) {
  return ownerOnlyUntil(/databases/$(db)/documents/battleship/$(id), uid, ['won', 'resigned']);
}

// The shot document: fired by the player on turn, named for their seat and the
// cell, at a cell on the board, with `hit` true exactly when the defender's
// fleet covers the cell. The match update in the same batch names it.
export function battleshipShotCreate(db, id, shotId) {
  let prefix = shotId[0:1];
  let cell = int(shotId[1:3]);
  let before = get(/databases/$(db)/documents/battleship/$(id)).data;
  let after = getAfter(/databases/$(db)/documents/battleship/$(id)).data;
  let seat = before.currentTurn;
  let defender = seat == 'host' ? before.guest : before.host;
  let fleet = get(/databases/$(db)/documents/battleship/$(id)/boards/$(defender)).data;
  return request.auth != null
    && shotId.size() == 3
    && before.status == 'playing'
    && request.auth.uid == before[seat]
    && prefix == (seat == 'host' ? 'h' : 'g')
    && cell >= 0 && cell <= 99
    && request.resource.data.keys().hasOnly(['by', 'cell', 'hit'])
    && request.resource.data.by == request.auth.uid
    && request.resource.data.cell == cell
    && request.resource.data.hit == (cell in fleet.cells)
    && after.lastShot == shotId
    && after.moveCount == before.moveCount + 1;
}

// The match update for a shot: it names a new shot document written in the
// same batch, adds its hit to the shooter's count, passes the turn, and ends
// the match when the shooter has hit all 17 cells.
export function battleshipShot(db, id) {
  let seat = resource.data.currentTurn;
  let shot = getAfter(/databases/$(db)/documents/battleship/$(id)/shots/$(request.resource.data.lastShot)).data;
  let hits = resource.data[seat + 'Hits'] + (shot.hit ? 1 : 0);
  return request.auth != null
    && resource.data.status == 'playing'
    && isMyTurn()
    && !exists(/databases/$(db)/documents/battleship/$(id)/shots/$(request.resource.data.lastShot))
    && shot.by == request.auth.uid
    && request.resource.data[seat + 'Hits'] == hits
    && request.resource.data.currentTurn == (seat == 'host' ? 'guest' : 'host')
    && request.resource.data.moveCount == resource.data.moveCount + 1
    && request.resource.data.status == (hits == 17 ? 'won' : 'playing')
    && request.resource.data.winner == (hits == 17 ? seat : '')
    && onlyFieldsChanged([seat + 'Hits', 'currentTurn', 'moveCount', 'lastShot', 'status', 'winner']);
}

// The caller resigns their own seat; the other seat wins.
export function battleshipResign() {
  return resignedBy(request.auth.uid == resource.data.host ? 'host' : 'guest');
}

modules.../games/checkers/checkers:
rules_version = '2+modules';

import { validCreate, validJoin, canCancel } from 'lobby';
import { onlyFieldsChanged } from 'lifecycle';
import { isMyTurn, turnFlipped } from 'turns';
import { isPlaying, moveIncremented } from 'state';
import { resignedBy } from 'results';
import { file, rank } from 'geometry';

// Checkers match rules. The host plays dark ('d', king 'D') and moves first;
// the guest plays light ('l', king 'L'). The match document follows the stdlib
// convention (host, guest, currentTurn, status, winner, moveCount) plus board
// (the 32 playable squares by name), prevBoard, and lastMove {path, captures}.
//
// These rules check what one move can change, and the geometry of a single
// step or jump. They don't check multi-jump geometry,
// mandatory captures, or a win claim; the clients replay each move from
// prevBoard and flag one that isn't legal checkers.

function checkersStartBoard() {
  return {
    'b8': 'l', 'd8': 'l', 'f8': 'l', 'h8': 'l',
    'a7': 'l', 'c7': 'l', 'e7': 'l', 'g7': 'l',
    'b6': 'l', 'd6': 'l', 'f6': 'l', 'h6': 'l',
    'a5': '', 'c5': '', 'e5': '', 'g5': '',
    'b4': '', 'd4': '', 'f4': '', 'h4': '',
    'a3': 'd', 'c3': 'd', 'e3': 'd', 'g3': 'd',
    'b2': 'd', 'd2': 'd', 'f2': 'd', 'h2': 'd',
    'a1': 'd', 'c1': 'd', 'e1': 'd', 'g1': 'd'
  };
}

// One diagonal square. Comparing file and rank differences costs less than
// testing each of the four neighbors with the geometry module's step().
function ckStep(from, to) {
  return (file(to) - file(from) == 1 || file(to) - file(from) == -1)
    && (rank(to) - rank(from) == 1 || rank(to) - rank(from) == -1);
}

// Two diagonal squares, over the captured square between them.
function ckJump(from, to, captured) {
  return (file(to) - file(from) == 2 || file(to) - file(from) == -2)
    && (rank(to) - rank(from) == 2 || rank(to) - rank(from) == -2)
    && file(captured) * 2 == file(from) + file(to)
    && rank(captured) * 2 == rank(from) + rank(to);
}

export function checkersCreate() {
  return validCreate()
    && request.resource.data.keys().hasOnly(['host', 'guest', 'currentTurn', 'status', 'winner', 'moveCount',
         'board', 'prevBoard', 'lastMove', 'createdAt', 'rematchOf'])
    && request.resource.data.currentTurn == 'host'
    && request.resource.data.winner == ''
    && request.resource.data.moveCount == 0
    && request.resource.data.createdAt == request.time
    && request.resource.data.board == checkersStartBoard()
    && request.resource.data.prevBoard == checkersStartBoard()
    && request.resource.data.lastMove == {'path': [], 'captures': []};
}

export function checkersJoin() {
  return validJoin() && onlyFieldsChanged(['guest', 'status']);
}

export function checkersCancel() {
  return canCancel();
}

// One move by the player on turn: a step (two squares, no captures) or a run
// of jumps (one capture per hop). A man is crowned only on the far row.
export function checkersMove() {
  let dark = resource.data.currentTurn == 'host';
  let path = request.resource.data.lastMove.path;
  let from = path[0];
  let to = path[path.size() - 1];
  let piece = resource.data.board[from];
  return request.auth != null && isPlaying() && isMyTurn() && turnFlipped() && moveIncremented()
    && request.resource.data.lastMove.keys().hasOnly(['path', 'captures'])
    && request.resource.data.lastMove.path.size() >= 2
    && (request.resource.data.lastMove.captures.size() == request.resource.data.lastMove.path.size() - 1
        || (request.resource.data.lastMove.captures.size() == 0 && request.resource.data.lastMove.path.size() == 2))
    && (path.size() > 2
        || (request.resource.data.lastMove.captures.size() == 0
            ? ckStep(from, to)
            : ckJump(from, to, request.resource.data.lastMove.captures[0])))
    && piece in (dark ? ['d', 'D'] : ['l', 'L'])
    && resource.data.board[to] == ''
    && request.resource.data.board[from] == ''
    && (request.resource.data.board[to] == piece
        || (piece == (dark ? 'd' : 'l') && request.resource.data.board[to] == (dark ? 'D' : 'L')
            && rank(to) == (dark ? 8 : 1)))
    && request.resource.data.board.keys().hasOnly(resource.data.board.keys())
    && request.resource.data.board.diff(resource.data.board).affectedKeys()
         .hasOnly([from, to].concat(request.resource.data.lastMove.captures))
    && request.resource.data.prevBoard == resource.data.board
    && request.resource.data.winner == (request.resource.data.status == 'won' ? resource.data.currentTurn : '')
    && onlyFieldsChanged(['board', 'prevBoard', 'lastMove', 'currentTurn', 'moveCount', 'status', 'winner']);
}

// The caller resigns their own seat; the other seat wins.
export function checkersResign() {
  return resignedBy(request.auth.uid == resource.data.host ? 'host' : 'guest');
}

modules.../games/chess/chess:
rules_version = '2+modules';

import { validCreate, validJoin, canCancel } from 'lobby';
import { onlyFieldsChanged } from 'lifecycle';
import { isMyTurn, turnFlipped } from 'turns';
import { isPlaying, moveIncremented } from 'state';
import { resignedBy } from 'results';

